// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Runs the all-vendor mirror around one cloud sync
// Flo: open a kit with every store and database > build the fan for the main vendor > after the sync: backfill new mirrors, drain the spools and queues, audit weekly > record vendor health and write alert lines
// I/O: vendor lists + Db + clock + Conf > Mres counts and alert lines; dry runs only count; a mirror problem is an alert, never a failed sync
// ===================================================================
const std = @import("std"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig"); const fail = @import("ru-fail-over.zig"); const sync = @import("sy-clou-sync.zig"); const mirr = @import("sy-mirr-stor.zig"); const audt = @import("sy-mirr-audt.zig"); const msql = @import("sy-mirr-sqlz.zig"); const quot = @import("sy-mirr-quot.zig");
const CF = .{ .rnds = 4 };
pub const Mres = struct { onzz: bool = false, sent: u32 = 0, qued: u32 = 0, drai: u32 = 0, left: i64 = 0, sqls: u32 = 0, sqlf: i64 = 0, quer: u32 = 0, bads: u32 = 0, orph: u32 = 0, back: u32 = 0, dead: u32 = 0, paus: u32 = 0 };
pub const Kitz = struct { smem: []const mirr.Memb, qmem: []const msql.Smem, sdea: mirr.Dead, qdea: mirr.Dead, sini: []bool, qini: []bool, ddlz: []bool, fanm: ?*mirr.Fanz = null, sanm: ?*msql.Sanz = null, fans: std.ArrayList(*mirr.Fanz) = .empty, sans: std.ArrayList(*msql.Sanz) = .empty };
pub fn kitzOpen(aren: std.mem.Allocator, dbzz: *sqli.Dbzz, nowz: i64, smem: []const mirr.Memb, qmem: []const msql.Smem) !*Kitz { const kitz = try aren.create(Kitz); kitz.* = .{ .smem = smem, .qmem = qmem, .sdea = try mirr.deadMake(aren, smem.len), .qdea = try mirr.deadMake(aren, qmem.len), .sini = try aren.alloc(bool, smem.len), .qini = try aren.alloc(bool, qmem.len), .ddlz = try aren.alloc(bool, qmem.len) }; @memset(kitz.ddlz, false); for (smem, 0..) |mem, indx| { kitz.sdea.dead[indx] = !try fail.failOkay(dbzz, mem.name, nowz); kitz.sini[indx] = kitz.sdea.dead[indx]; } for (qmem, 0..) |mem, indx| { kitz.qdea.dead[indx] = !try fail.failOkay(dbzz, mem.name, nowz); kitz.qini[indx] = kitz.qdea.dead[indx]; } return kitz; }
pub fn vendFail(kitz: *Kitz, isst: bool, indx: usize) void { if (isst) { kitz.sdea.dead[indx] = true; kitz.sini[indx] = true; } else { kitz.qdea.dead[indx] = true; kitz.qini[indx] = true; } }
pub fn fanzForz(kitz: *Kitz, aren: std.mem.Allocator, dbzz: *sqli.Dbzz, iozz: std.Io, nowz: i64, conf: cfgz.Conf, prim: usize, main: bool) !*mirr.Fanz { const mirs = try aren.alloc(mirr.Memb, kitz.smem.len - 1); var fill: usize = 0; for (kitz.smem, 0..) |mem, indx| { if (indx == prim) continue; mirs[fill] = mem; fill += 1; } const outp = try aren.create(mirr.Fanz); outp.* = .{ .dbzz = dbzz, .iozz = iozz, .nowz = nowz, .conf = conf, .prim = kitz.smem[prim], .mirs = mirs, .stat = &kitz.sdea }; try kitz.fans.append(aren, outp); if (main) kitz.fanm = outp; return outp; }
pub fn sanzForz(kitz: *Kitz, aren: std.mem.Allocator, dbzz: *sqli.Dbzz, iozz: std.Io, nowz: i64, conf: cfgz.Conf, prim: usize) !*msql.Sanz { const mirs = try aren.alloc(msql.Smem, kitz.qmem.len - 1); var fill: usize = 0; for (kitz.qmem, 0..) |mem, indx| { if (indx == prim) continue; mirs[fill] = mem; fill += 1; } const outp = try aren.create(msql.Sanz); outp.* = .{ .dbzz = dbzz, .iozz = iozz, .nowz = nowz, .conf = conf, .prim = kitz.qmem[prim], .mirs = mirs, .stat = &kitz.qdea, .ddlz = kitz.ddlz }; try kitz.sans.append(aren, outp); kitz.sanm = outp; return outp; }
fn alrtAddz(aren: std.mem.Allocator, list: *std.ArrayList([]const u8), comptime fmtz: []const u8, args: anytype) !void { try list.append(aren, try std.fmt.allocPrint(aren, fmtz, args)); }
fn vendRepo(aren: std.mem.Allocator, dbzz: *sqli.Dbzz, nowz: i64, conf: cfgz.Conf, dead: *const mirr.Dead, inis: []const bool, list: anytype, what: []const u8, isst: bool, alrt: *std.ArrayList([]const u8), mres: *Mres) !void { for (list, 0..) |mem, indx| { if (dead.dead[indx] and !inis[indx]) { const err3 = dead.errz[indx]; try fail.failBadz(dbzz, mem.name, nowz, err3 == error.CloudDeny, conf.clou_fail_runs); mres.dead += 1; try alrtAddz(aren, alrt, "mirror {s} ({s}) failed: {s}; its work waits in a queue and it is retried next run", .{ mem.name, what, @errorName(err3) }); } else if (dead.used[indx] and !dead.dead[indx]) try fail.failGood(dbzz, mem.name); if (!isst) continue; if (dead.paus[indx]) { mres.paus += 1; try alrtAddz(aren, alrt, "mirror {s}: monthly call budget of {d} is used up; it is paused until next month and its objects wait in the queue", .{ mem.name, conf.clou_mirr_opsa_mont }); } else if (try quot.opsaHigh(dbzz, mem.name, nowz, conf.clou_mirr_opsa_mont)) try alrtAddz(aren, alrt, "mirror {s}: {d} of {d} monthly calls used (over 80%)", .{ mem.name, try quot.opsaGetz(dbzz, mem.name, nowz), conf.clou_mirr_opsa_mont }); } }
pub fn kitzFini(kitz: *Kitz, aren: std.mem.Allocator, dbzz: *sqli.Dbzz, nowz: i64, conf: cfgz.Conf, synz: *sync.Sync, alrt: *std.ArrayList([]const u8), dryz: bool) !Mres { var mres: Mres = .{ .onzz = true }; for (kitz.fans.items) |fanz| { mres.sent += fanz.sent; mres.qued += fanz.qued; } for (kitz.sans.items) |sanz| mres.sqls += sanz.sent; if (dryz) return mres; const fanz = kitz.fanm orelse return mres; const sanz = kitz.sanm orelse return mres; mres.back = msql.sanzBack(sanz, aren, synz) catch 0; var rnds: u8 = 0; while (rnds < CF.rnds) : (rnds += 1) { if ((msql.sanzLeft(sanz) catch 0) == 0) break; msql.sanzDrai(sanz, aren) catch break; } if (mirr.fanzDrai(fanz, aren)) |dres| { mres.drai = dres.done; } else |_| {} if (audt.fanzAudt(fanz, aren)) |ares| { mres.quer = ares.quer; mres.bads = ares.bads; mres.orph = ares.orph; if (ares.quer + ares.bads > 0) { if (mirr.fanzDrai(fanz, aren)) |dre2| { mres.drai += dre2.done; } else |_| {} } } else |_| {} mres.left = mirr.fanzLeft(fanz) catch 0; mres.sqlf = msql.sanzLeft(sanz) catch 0; try vendRepo(aren, dbzz, nowz, conf, &kitz.sdea, kitz.sini, kitz.smem, "store", true, alrt, &mres); try vendRepo(aren, dbzz, nowz, conf, &kitz.qdea, kitz.qini, kitz.qmem, "database", false, alrt, &mres); for (sanz.drps.items) |name| try alrtAddz(aren, alrt, "mirror {s}: database spool passed {d} statements and was dropped; a full backfill restarts", .{ name, conf.clou_mirr_spoo_maxz }); return mres; }
